import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

sigmoid_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void sigmoid_kernel_vec4(const float4* __restrict__ input,
                                     float4* __restrict__ output,
                                     int64_t n_vec4) {
    int64_t idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
    int64_t stride = gridDim.x * (int64_t)blockDim.x;

    for (int64_t i = idx; i < n_vec4; i += stride) {
        float4 in = input[i];
        float4 out;
        out.x = 1.0f / (1.0f + __expf(-in.x));
        out.y = 1.0f / (1.0f + __expf(-in.y));
        out.z = 1.0f / (1.0f + __expf(-in.z));
        out.w = 1.0f / (1.0f + __expf(-in.w));
        output[i] = out;
    }
}

__global__ void sigmoid_kernel_scalar(const float* __restrict__ input,
                                       float* __restrict__ output,
                                       int64_t n,
                                       int64_t offset) {
    int64_t idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x + offset;
    if (idx < n) {
        output[idx] = 1.0f / (1.0f + __expf(-input[idx]));
    }
}

torch::Tensor sigmoid_cuda(torch::Tensor x) {
    auto x_contig = x.contiguous();
    auto output = torch::empty_like(x_contig);

    int64_t n = x_contig.numel();
    int64_t n_vec4 = n / 4;
    int64_t remainder = n % 4;

    const float* input_ptr = x_contig.data_ptr<float>();
    float* output_ptr = output.data_ptr<float>();

    const int threads = 256;

    if (n_vec4 > 0) {
        int64_t blocks = (n_vec4 + threads - 1) / threads;
        if (blocks > 65535) blocks = 65535;
        sigmoid_kernel_vec4<<<blocks, threads>>>(
            reinterpret_cast<const float4*>(input_ptr),
            reinterpret_cast<float4*>(output_ptr),
            n_vec4
        );
    }

    if (remainder > 0) {
        int64_t offset = n_vec4 * 4;
        int blocks = (remainder + threads - 1) / threads;
        sigmoid_kernel_scalar<<<blocks, threads>>>(input_ptr, output_ptr, n, offset);
    }

    return output;
}
"""

sigmoid_cpp_source = "torch::Tensor sigmoid_cuda(torch::Tensor x);"

sigmoid_module = load_inline(
    name="sigmoid_module",
    cpp_sources=sigmoid_cpp_source,
    cuda_sources=sigmoid_source,
    functions=["sigmoid_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Sigmoid activation using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.sigmoid_op = sigmoid_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.sigmoid_op.sigmoid_cuda(x)


